def is_valid_bst_wrong(root, parent=None, is_left=None):
    # INCORRECT: only checks the direct parent-child relationship,
    # missing constraints from higher ancestors
    if root is None:
        return True
    if parent is not None:
        if is_left and root.val >= parent.val:
            return False
        if not is_left and root.val <= parent.val:
            return False
    return (is_valid_bst_wrong(root.left, root, True)
            and is_valid_bst_wrong(root.right, root, False))

