def is_valid_bst(root):
    def valid(node, lo, hi):
        if node is None:
            return True
        if node.val <= lo or node.val >= hi:                # strictly within (lo, hi)
            return False
        return (valid(node.left, lo, node.val)                 # narrow upper bound going left
                and valid(node.right, node.val, hi))            # narrow lower bound going right
    return valid(root, float('-inf'), float('inf'))

