bool valid(TreeNode* node, long long lo, long long hi) {
    if (!node) return true;
    if (node->val <= lo || node->val >= hi) return false;             // strictly within (lo, hi)
    return valid(node->left, lo, node->val)                              // narrow upper bound going left
        && valid(node->right, node->val, hi);                              // narrow lower bound going right
}

